import React, { useEffect, useState } from "react";
import axios from "axios";
import "./App.css"; // Import the CSS file

function App() {
  const [nodes, setNodes] = useState({});
  const [cpuCores, setCpuCores] = useState("");

  const API_URL = "http://localhost:5000/api/nodes";

  const fetchNodes = async () => {
    try {
      const response = await axios.get(API_URL);
      setNodes(response.data);
    } catch (error) {
      console.error("Error fetching nodes:", error);
    }
  };

  const addNode = async () => {
    try {
      const cores = parseInt(cpuCores);
      if (isNaN(cores) || cores <= 0) return alert("Invalid CPU core count");

      const response = await axios.post(API_URL, {
        cpu_cores: cores,
      });
      setCpuCores("");
      fetchNodes();
    } catch (error) {
      console.error("Error adding node:", error);
    }
  };

  const deleteNode = async (id) => {
    try {
      await axios.delete(`${API_URL}/${id}`);
      fetchNodes();
    } catch (error) {
      console.error("Error deleting node:", error);
    }
  };

  useEffect(() => {
    fetchNodes(); // initial call

    const interval = setInterval(() => {
      fetchNodes();
    }, 5000); // fetch every 5 seconds

    return () => clearInterval(interval); // cleanup
  }, []);

  return (
    <div className="container">
      <h1 className="title">🚀 Node Dashboard</h1>

      <div className="form">
        <input
          type="number"
          placeholder="Enter CPU cores"
          value={cpuCores}
          onChange={(e) => setCpuCores(e.target.value)}
          className="input"
        />
        <button onClick={addNode} className="button">
          Add Node
        </button>
      </div>

      <h2 className="subtitle">🧠 All Nodes</h2>

      {Object.keys(nodes).length === 0 ? (
        <p className="noNodes">No nodes available.</p>
      ) : (
        <div className="nodeList">
          {Object.entries(nodes).map(([id, node]) => (
            <div key={id} className="nodeCard">
              <p>
                <strong>ID:</strong> {node.id}
              </p>
              <p>
                <strong>Status:</strong>{" "}
                <span
                  style={{ color: node.status === "Running" ? "green" : "red" }}
                >
                  {node.status}
                </span>
              </p>
              <p>
                <strong>CPU:</strong> {node.cpu}
              </p>
              <p>
                <strong>Available CPU:</strong> {node.available_cpu}
              </p>
              <p>
                <strong>Last Heartbeat:</strong>{" "}
                {node.last_heartbeat.toFixed(2)}s ago
              </p>
              <button onClick={() => deleteNode(id)} className="deleteButton">
                Delete
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default App;
